from primitive_api import (
    recall_visible_objects, read_observed_spatial_map, look,
    inspect_current_view, check_progress_public
)

mem = {
    q: recall_visible_objects(query=q, limit=20)
    for q in ["Cabinet", "Drawer", "Dishwasher", "SaltShaker", "Fridge"]
}
look_result = look("down")
view5 = inspect_current_view(label="lower_counter_view", remember=True)
current_relevant = [
    o for o in view5.get("visible_objects", [])
    if o.get("objectType") in {"Cabinet", "Drawer", "Dishwasher", "SaltShaker", "Fridge", "CounterTop"}
]

print({
    "pose": view5.get("observation", {}).get("agent"),
    "current_relevant": current_relevant,
    "remembered": mem,
    "spatial_map": read_observed_spatial_map(limit=20),
    "look_ok": look_result.get("valid_action"),
    "progress": check_progress_public(),
    "frame": view5.get("frame"),
})

from primitive_api import (
    open_object, close_object, pickup_object, put_object,
    detect_objects, query_inventory, inspect_current_view, check_success, observe
)

cabinet_id = "Cabinet|+00.65|+00.48|-01.72"
target_drawer_id = "Drawer|+00.64|+00.55|-00.65"  # middle/second pullout drawer

actions7 = {}
actions7["open_cabinet"] = open_object(cabinet_id)
after_open = inspect_current_view(label="opened_salt_cabinet", remember=True)

salts = detect_objects("SaltShaker")
if salts:
    actions7["pickup_salt"] = pickup_object(salts[0]["objectId"])

inventory7 = query_inventory()

if inventory7:
    # Close the source cabinet so its door cannot obstruct the adjacent drawers.
    visible_cab = detect_objects(cabinet_id)
    if visible_cab:
        actions7["close_cabinet"] = close_object(cabinet_id)

    drawers = detect_objects("Drawer")
    target_visible = [d for d in drawers if d["objectId"] == target_drawer_id]
    if target_visible:
        actions7["open_target_drawer"] = open_object(target_drawer_id)
        # Re-ground after opening before placement.
        opened_drawers = detect_objects("Drawer")
        target_open = [d for d in opened_drawers if d["objectId"] == target_drawer_id]
        if target_open:
            actions7["put_salt"] = put_object(inventory7[0]["objectId"], target_drawer_id)

final7 = inspect_current_view(label="after_direct_manipulation", remember=True)
print({
    "actions": {
        k: {
            "valid": v.get("valid_action"),
            "error": v.get("error"),
        } for k, v in actions7.items()
    },
    "salt_seen_after_open": salts,
    "inventory": query_inventory(),
    "visible_drawers": detect_objects("Drawer"),
    "pose": observe().get("agent"),
    "success": check_success(),
    "frame": final7.get("frame"),
})

from primitive_api import (
    rotate, move_ahead, look, detect_objects, pickup_object,
    open_object, put_object, query_inventory, inspect_current_view,
    check_success, observe
)

events8 = []

def find_salt():
    hits = detect_objects("SaltShaker")
    if not hits:
        hits = detect_objects("Salt")
    return hits

# Reposition directly in front of the already-open lower cabinet.
events8.append(("face_south", rotate("right")))
events8.append(("step_south", move_ahead()))
events8.append(("face_cabinet", rotate("left")))
salts8 = find_salt()

if not salts8:
    events8.append(("look_further_down", look("down")))
    salts8 = find_salt()

# If the stove edge still occludes the cabinet interior, move farther south
# and face east again for a nearly head-on view.
if not salts8:
    events8.append(("face_south_2", rotate("right")))
    events8.append(("step_south_2", move_ahead()))
    events8.append(("face_cabinet_2", rotate("left")))
    salts8 = find_salt()

pickup8 = None
if salts8:
    pickup8 = pickup_object(salts8[0]["objectId"])

inv8 = query_inventory()
drawer_id = "Drawer|+00.64|+00.55|-00.65"

# From the cabinet, the drawer bank is to the north-east. Reorient if needed,
# open the middle (second) pullout drawer, and place the held shaker.
open_drawer8 = None
put8 = None
if inv8:
    visible_drawers = detect_objects("Drawer")
    if not any(d["objectId"] == drawer_id for d in visible_drawers):
        events8.append(("face_drawers_north", rotate("left")))
        visible_drawers = detect_objects("Drawer")
    if any(d["objectId"] == drawer_id for d in visible_drawers):
        open_drawer8 = open_object(drawer_id)
        if open_drawer8.get("valid_action"):
            put8 = put_object(inv8[0]["objectId"], drawer_id)

final_view8 = inspect_current_view(label="final_task_state", remember=True)
print({
    "pose": observe().get("agent"),
    "salt_candidates": salts8,
    "pickup": None if pickup8 is None else {
        "valid": pickup8.get("valid_action"), "error": pickup8.get("error")
    },
    "open_drawer": None if open_drawer8 is None else {
        "valid": open_drawer8.get("valid_action"), "error": open_drawer8.get("error")
    },
    "put": None if put8 is None else {
        "valid": put8.get("valid_action"), "error": put8.get("error")
    },
    "inventory": query_inventory(),
    "success": check_success(),
    "events_used": len(events8),
    "frame": final_view8.get("frame"),
})
